        "la t1, tohost\n"  // Load address of tohost into t1
        "li t0, 1\n"       // Load value 1 into t0
        "sd t0, 0(t1)\n"   // Store t0 to address in t1 (i.e., tohost)
        "1: j 1b\n" // Infinite loop to terminate simulation
